/* take the privileged resource first, then drop everything else */
int fd = open("/dev/port0", O_RDWR | O_CLOEXEC);    /* needs root briefly */
if (fd < 0) die("open");
if (setgroups(0, NULL) != 0) die("setgroups");       /* no stray group rights */
if (setresgid(-1, gid, gid) != 0) die("setresgid");  /* not re-acquirable */
if (setresuid(-1, uid, uid) != 0) die("setresuid");  /* saved-set is gone */
/* from here the process can only do what uid/gid permit */
serve(fd);

