cap_t caps = cap_get_proc();
cap_value_t keep[] = { CAP_NET_BIND_SERVICE };
cap_set_flag(caps, CAP_EFFECTIVE, 1, keep, CAP_SET);
cap_set_flag(caps, CAP_PERMITTED, 1, keep, CAP_SET);
if (cap_set_proc(caps) != 0) die("cap_set_proc");
/* the bounding set is what execve can never grant back: drop it too */
if (prctl(PR_CAPBSET_DROP, CAP_SYS_ADMIN, 0, 0, 0) != 0) die("prctl");
cap_free(caps);
